def transform(grid):
    h, w = len(grid), len(grid[0])
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r][c - 1] == grid[r][c + 1] ==
                    grid[r - 1][c] == grid[r + 1][c] == 3):
                crosses.append((r, c, grid[r][c]))

    colored = [(r, c, color) for r, c, color in crosses if color != 0 and color != 3]
    neutral = [(r, c) for r, c, color in crosses if color == 0]
    markers = {}
    for r, c, color in colored:
        for p in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            markers.setdefault(p, set()).add((r, c))

    horizontal = [[None] * w for _ in range(h)]
    vertical = [[None] * w for _ in range(h)]

    for r, c, color in colored:
        # Horizontal rays
        for dc in (-1, 1):
            j = c + dc
            while 0 <= j < w:
                if grid[r][j] != 0:
                    if grid[r][j] == 3 and (r, j) in markers and (r, c) not in markers[(r, j)]:
                        break
                    if grid[r][j] != 3:
                        break
                if not any(j == nc for nr, nc in neutral):
                    horizontal[r][j] = color
                j += dc

        # Vertical rays
        for dr in (-1, 1):
            i = r + dr
            while 0 <= i < h:
                if grid[i][c] != 0:
                    if grid[i][c] == 3 and (i, c) in markers and (r, c) not in markers[(i, c)]:
                        break
                    if grid[i][c] != 3:
                        break
                vertical[i][c] = color
                i += dr

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                if horizontal[r][c] is not None:
                    out[r][c] = horizontal[r][c]
                if vertical[r][c] is not None:
                    out[r][c] = vertical[r][c]
    return out
